using namespace std;

const long long MOD = 1000000007;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    string s;
    cin >> n >> s;

    long long ans = 0;
    long long sumNonzero = 0; // S_{j-1}

    for (int j = 1; j <= n; ++j) {
        char ch = s[j - 1];
        // 判断偶数
        if (ch == '0' || ch == '2' || ch == '4' || ch == '6' || ch == '8') {
            long long factor = (n - j + 1) % MOD;
            long long contribution = (sumNonzero + j) % MOD;
            ans = (ans + contribution * factor) % MOD;
        }
        // 更新非零位置前缀和
        if (ch != '0') {
            sumNonzero = (sumNonzero + j) % MOD;
        }
    }

    cout << ans << "\n";
    return 0;
}
